// Minimal local fallback for PrefixFree (no-op fallback)
// This file is provided so the onerror fallback in index.html has a valid local script to load.
// It does not implement full prefixing behavior. If you need full PrefixFree functionality,
// replace this file with the original prefixfree.min.js contents.

(function(){
  if (typeof console !== 'undefined') {
    console.info('Local prefixfree fallback loaded (minimal no-op).');
  }
  // Minimal shim: ensure window.PrefixFree exists so other scripts don't throw when checking it.
  if (!window.PrefixFree) {
    window.PrefixFree = {
      // no-op function for compatibility
      process: function(){ return; }
    };
  }
})();
